test('invoiceTotals: single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.deepStrictEqual(totals, { subtotal: 42500, discount: 0, total: 42500 });
});

test('invoiceTotals: multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 2, unitPrice: 980 },
      { qty: 100, unitPrice: 37 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 10 * 9500 + 2 * 980 + 100 * 37;
  assert.strictEqual(totals.subtotal, expected);
  assert.strictEqual(totals.total, expected);
});

test('invoiceTotals: equal subtotal and total (VAT not yet implemented)', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 120000 },
      { qty: 1, unitPrice: 245000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.strictEqual(totals.subtotal, totals.total);
  assert.strictEqual(totals.subtotal, 365000);
});

