test('addLine: add new line to draft invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.strictEqual(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });
  assert.strictEqual(result.ok, true);
  const newInvoice = result.value;
  assert.strictEqual(newInvoice.lines.length, 2);
  assert.strictEqual(newInvoice.lines[0].sku, 'DES-HOUR');
  assert.strictEqual(newInvoice.lines[1].sku, 'DEV-HOUR');
  assert.strictEqual(newInvoice.lines[1].qty, 3);
  assert.strictEqual(newInvoice.lines[1].name, 'Development (hour)');
  assert.strictEqual(newInvoice.lines[1].unitPrice, 9500);
});

